'use client';import { questions } from '../../../lib/questions';import {useParams,useRouter} from 'next/navigation';import {useEffect,useState} from 'react';
export default function Test(){const {coupleId}=useParams<{coupleId:string}>();const r=useRouter();const[i,setI]=useState(0);const[a,setA]=useState<Record<string,string>>({});const[role,setRole]=useState<'a'|'b'>('a');useEffect(()=>{setRole((localStorage.getItem(`role:${coupleId}`) as 'a'|'b')||'a')},[coupleId]);const q=questions[i];async function answer(v:string){const next={...a,[q.id]:v};setA(next);if(i<questions.length-1){setI(i+1)}else{await fetch('/api/answers',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({coupleId,role,answers:next})});r.push(role==='a'?`/waiting/${coupleId}`:`/result/${coupleId}`)}}return <main className="shell"><div className="progress"><div style={{width:`${((i+1)/questions.length)*100}%`}}/></div><p className="tiny">{i+1} / {questions.length}</p><div className="question">{q.text}</div>{q.type==='scale'?<div className="options">{[1,2,3,4,5].map(n=><button className="option" key={n} onClick={()=>answer(String(n))}>{n} {n===1?'— совсем нет':n===5?'— полностью':''}</button>)}</div>:q.type==='choice'?<div className="options">{q.options!.map(o=><button className="option" key={o} onClick={()=>answer(o)}>{o}</button>)}</div>:<Text go={answer}/>}</main>}
function Text({go}:{go:(v:string)=>void}){const[v,setV]=useState('');return <><textarea className="input" rows={5} value={v} onChange={e=>setV(e.target.value)} placeholder="Напиши своими словами…"/><button className="btn" onClick={()=>v.trim()&&go(v.trim())}>Продолжить</button></>}
